<div class="gadsan-page-heading"><div><h2><i class="bi bi-file-earmark-check me-2" aria-hidden="true"></i><?= ge($import['nome_arquivo']) ?></h2><p>Importação #<?= (int)$import['id'] ?> · <?= ge(str_replace('_',' ',$import['status'])) ?></p></div><div class="gadsan-heading-actions"><a class="btn btn-light" href="/admin/gadsan/importacoes"><i class="bi bi-arrow-left me-1"></i>Voltar às importações</a></div></div>

<div class="gadsan-import-summary mb-3"><span class="gadsan-badge <?= in_array($import['status'],['concluida','ja_importado'],true)?'gadsan-badge-success':($import['status']==='falhou'?'gadsan-badge-warning':'') ?>"><i class="bi bi-circle-fill me-1" style="font-size:.45rem" aria-hidden="true"></i><?= ge(str_replace('_',' ',$import['status'])) ?></span><?php if (!empty($import['data_importacao'])): ?><span><i class="bi bi-calendar3 me-1" aria-hidden="true"></i><?= ge($import['data_importacao']) ?></span><?php endif ?></div>
<div class="gadsan-stats">
  <?php foreach ([['total_linhas','Linhas recebidas','bi-list-ol'],['total_importados','Novos colaboradores','bi-person-plus'],['total_ignorados','Sem novo cadastro','bi-person-dash'],['total_inconsistencias','Alertas registrados','bi-exclamation-diamond']] as [$key,$label,$icon]): ?><div class="gadsan-stat"><span class="gadsan-stat-icon"><i class="bi <?= $icon ?>" aria-hidden="true"></i></span><span><strong><?= (int)$import[$key] ?></strong><span><?= ge($label) ?></span></span></div><?php endforeach ?>
</div>

<details class="card mb-4"><summary class="card-header" style="cursor:pointer"><strong><i class="bi bi-clipboard2-check me-2" aria-hidden="true"></i>Resumo das inconsistências</strong></summary><div class="card-body"><ul class="mb-0 ps-3"><?php foreach ($pending as $row): ?><li><?= ge(str_replace('_',' ',$row['tipo_inconsistencia'])) ?>: <strong><?= (int)$row['pendentes'] ?></strong> pendente(s) de <?= (int)$row['total'] ?></li><?php endforeach ?><?php if (!$pending): ?><li>Nenhum alerta registrado nesta importação.</li><?php endif ?></ul></div></details>

<div class="gadsan-table-wrap"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Aba / linha</th><th>Resultado</th><th>Colaborador</th><th class="text-end">Conferência</th></tr></thead><tbody>
<?php foreach ($origins as $row): ?><tr><td data-label="Aba / linha"><strong><?= ge($row['aba']) ?></strong><small class="d-block text-muted">Linha <?= (int)$row['linha'] ?></small></td><td data-label="Resultado"><span class="gadsan-badge"><?= ge(str_replace('_',' ',$row['resultado'])) ?></span></td><td data-label="Colaborador"><?php if ($row['colaborador_id']&&$canView): ?><a href="/admin/gadsan/colaboradores/<?= (int)$row['colaborador_id'] ?>">Cadastro #<?= (int)$row['colaborador_id'] ?></a><?php else: ?><span class="text-muted">Sem cadastro acessível</span><?php endif ?></td><td data-label="Conferência" class="text-end"><a href="/admin/gadsan/origens/<?= (int)$row['id'] ?>" class="btn btn-sm btn-outline-primary"><i class="bi bi-search me-1"></i>Ver origem</a></td></tr><?php endforeach ?>
<?php if (!$origins): ?><tr><td colspan="4" class="gadsan-empty"><i class="bi bi-inbox" aria-hidden="true"></i><strong>Nenhuma linha persistida</strong><span class="d-block mt-1">Esta carga ainda não possui registros para conferir.</span></td></tr><?php endif ?>
</tbody></table></div></div>
<nav class="gadsan-pagination" aria-label="Paginação das origens"><?php if ($page>1): ?><a class="btn btn-light" href="?pagina=<?= $page-1 ?>">Anterior</a><?php else: ?><span></span><?php endif ?><span>Página <?= (int)$page ?></span><?php if ($page*25<$total): ?><a class="btn btn-light" href="?pagina=<?= $page+1 ?>">Próxima</a><?php else: ?><span></span><?php endif ?></nav>
